import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    def normalize(fields):
        width = 5
        if len(fields) > width:
            # Recover unquoted commas in the free-text field before status.
            return fields[:3] + [",".join(fields[3:-1]), fields[-1]]
        return fields + [""] * (width - len(fields))

    for header in reader:
        if header:
            return {
                "columns": normalize(header),
                "rows": [normalize(row) for row in reader],
            }

    return {"columns": [], "rows": []}
